var u=new Intl.NumberFormat("en-IN",{maximumFractionDigits:0});function o(n){return n==null?"\u2013":u.format(n)}function i(n){if(n==null)return"\u2013";let r=Math.abs(n);return r>=1e7?`${e(n/1e7,2)} Cr`:r>=1e5?`${e(n/1e5,1)} L`:u.format(n)}function m(n,r=1){return n==null?"\u2013":`${Number(n).toFixed(r)}%`}function c(n,r){return n==null||r==null||Number(r)===0?null:(Number(n)-Number(r))/Math.abs(Number(r))*100}function e(n,r){let t=n.toFixed(r);return t.includes(".")?t.replace(/0+$/,"").replace(/\.$/,""):t}export{o as a,i as b,m as c,c as d};
